import hashlib
import unittest

from app.canonical import serialize
from app.http import handle_get


class Sheets:
    def __init__(self, body):
        self.body = body
        self.loaded_tenants = []

    def load(self, tenant):
        self.loaded_tenants.append(tenant)
        return self.body


class HandleGetTests(unittest.TestCase):
    settings = {
        "edge": {
            "variant_header": "X-Account",
            "stale_window_seconds": 900,
        }
    }

    def test_returns_canonical_etag_and_revalidation_headers(self):
        body = {"version": "round-7", "lines": [{"rate": 12, "sku": "A"}]}
        sheets = Sheets(body)

        response = handle_get(
            {"path": "/v3/price-sheet", "headers": {"X-Account": "tenant-a"}},
            sheets,
            self.settings,
        )

        expected_etag = '"%s"' % hashlib.sha256(serialize(body)).hexdigest()
        self.assertEqual(200, response["status"])
        self.assertEqual(body, response["body"])
        self.assertEqual(expected_etag, response["headers"]["ETag"])
        self.assertEqual("X-Account", response["headers"]["Vary"])
        self.assertEqual(
            "public, max-age=0, must-revalidate",
            response["headers"]["Cache-Control"],
        )
        self.assertEqual(str(len(serialize(body))), response["headers"]["Content-Length"])
        self.assertEqual(["tenant-a"], sheets.loaded_tenants)

    def test_equivalent_representations_have_the_same_etag(self):
        first = {"version": "round-7", "lines": [{"rate": 12, "sku": "A"}]}
        reordered = {"lines": [{"sku": "A", "rate": 12}], "version": "round-7"}

        first_response = handle_get({"headers": {}}, Sheets(first), self.settings)
        reordered_response = handle_get({"headers": {}}, Sheets(reordered), self.settings)

        self.assertEqual(
            first_response["headers"]["ETag"],
            reordered_response["headers"]["ETag"],
        )

    def test_matching_if_none_match_returns_304_without_a_body(self):
        body = {"version": "round-7", "lines": [{"rate": 12, "sku": "A"}]}
        etag = '"%s"' % hashlib.sha256(serialize(body)).hexdigest()

        response = handle_get(
            {"headers": {"X-Account": "tenant-a", "If-None-Match": etag}},
            Sheets(body),
            self.settings,
        )

        self.assertEqual(
            {
                "status": 304,
                "headers": {
                    "ETag": etag,
                    "Vary": "X-Account",
                    "Cache-Control": "public, max-age=0, must-revalidate",
                },
                "body": None,
            },
            response,
        )

    def test_rate_correction_inside_version_returns_new_body_and_etag(self):
        original = {"version": "round-7", "lines": [{"rate": 12, "sku": "A"}]}
        original_etag = '"%s"' % hashlib.sha256(serialize(original)).hexdigest()
        corrected = {"version": "round-7", "lines": [{"rate": 13, "sku": "A"}]}

        response = handle_get(
            {"headers": {"X-Account": "tenant-a", "If-None-Match": original_etag}},
            Sheets(corrected),
            self.settings,
        )

        self.assertEqual(200, response["status"])
        self.assertEqual(corrected, response["body"])
        self.assertNotEqual(original_etag, response["headers"]["ETag"])


if __name__ == "__main__":
    unittest.main()

